style.css:
body {
  background-image: url('https://i.pinimg.com/736x/fb/aa/76/fbaa760c392c6c575cc2c516380bc0f8.jpg');
  background-size: cover;  /* Ensures the image covers the entire screen */
  background-position: center center;  /* Centers the image on the page */
  background-repeat: no-repeat;  /* Ensures the image doesn't repeat */
  margin: 0;
  height: 100vh;  /* Makes the background cover the entire viewport height */
}
